   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="比起华而不实的宝石匣子，黑与白的秘辛更为珍贵。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
