   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="渡鸦很明显有些兴奋。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="潘多拉之盒，在二十多年前被一对著名的盗贼“乌鸦与白鸽”从尤赞坦的伊南姆家族偷走，此后这个家族的人一直在寻找这对盗贼，可惜的是直到伊南姆败落都没能成功。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="根据对外公布的信息，这个盒子用特制的金属打造，外面镶嵌着各种华丽的宝石拼花，即使忽略它里面的物品，这件东西本身也是一件价值连城的宝物。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当然，和原本存放在里面的物品相比，这些昂贵的宝石也不值一提——它能让一个普通人获得高水平的星源共鸣力量，具体是什么已然不可考，在它被打开的时候，里面的东西就因为力量的转移而烟消云散了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你收拢思绪，看着屏幕另一边的渡鸦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
