   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="乌鸦与白鸽，一对在泰诺星声名赫赫的盗贼，以三十年前盗走克罗瓦德国立博物馆的一件珍藏为开端，高调出场，并在往后的十年里活跃于泰诺星各处。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [143]={next_id=144, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="十年间，这两个名字让泰诺星那些财团和大家族恨得牙痒痒，而无数的穷人又成了这两人最坚定的支持者。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [144]={next_id=145, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="直到二十年前，这对侠盗盗走了潘多拉之盒，之后宣布金盆洗手，从此在泰诺星失去了踪迹——当然，这反而更让这两人声名大噪。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们的义举仍然被各种街头小报或者杂志所传扬，还有无数的窃贼仿效他们的行为——譬如那位灰鹭。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但是我有一点十分好奇。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们宣布金盆洗手曾经轰动一时，当时说不会再次复出。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [148]={next_id=149, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果这封信确实是他们寄来的，他们又想做什么？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="渡鸦也露出思索的神情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果密信中所指明的正是那座欢诞之所，那儿必然会有什么值得他们在意的珍宝。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="黑与白将匿身众人之中，伺机窥见奇珍的秘辛。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而深渊的双目将与鸦羽同行，直至见到他们的真容。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不论他们有什么目的，我相信他们绝对没有恶意。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [154]={next_id=155, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这就是渡鸦的判断。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [155]={next_id=156, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="至于那个虚华的宝匣……", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [156]={next_id=157, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我姑且承认它的价值，但寻回它不过是为了那个托付它的人——", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [157]={next_id=158, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="渡鸦的话音顿住了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="怎么了？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [159]={next_id=160, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="渡鸦蹙眉，有些欲言又止。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [160]={next_id=161, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她拿着终端，似乎十分焦躁地在房间里来回走了几步。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [161]={next_id=162, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="玩家名字，我有一个猜测。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [162]={next_id=163, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="关于那个宝石匣子。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [163]={next_id=164, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的眉毛都蹙在了一起，一下子甚至失去了身为深渊使者的素养。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [164]={next_id=165, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我想应该在爸妈回来之前解决好这件事。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [165]={next_id=166, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们的工作已经够忙了，不能让他们因为这种事情担心。", msg_color="", msg_size=0, talker="渡鸦", audio="", img="arts/ui/bg/story/storybg_211.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4103_1", 0, 1, 40.5, 230.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
